const user = $('Perparer_par_user').item.json;

// 1) Lire la réponse du LLM (texte contenant du JSON)
const raw = $json.content?.parts?.[0]?.text ?? '';
let selection = [];
try {
  const clean = raw.replace(/```json|```/g, '').trim();
  selection = JSON.parse(clean).selection || [];
} catch (e) {
  selection = [];
}

// 2) Retrouver les articles par leur numéro, avec les URLs de NOS données
const vus = new Set();
const choisis = [];
for (const s of selection) {
  const a = user.articles[Number(s.id)];
  if (!a || !/^https?:\/\//.test(a.url) || vus.has(a.url)) continue;
  vus.add(a.url);
  choisis.push({ titre: a.titre, url: a.url, source: a.source, resume: String(s.resume ?? '') });
}
const top = choisis.slice(0, 6);

// 3) Construire l'email (texte échappé pour le HTML)
const esc = (s) => String(s ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;')
  .replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const date = new Date().toLocaleDateString('fr-FR', {
  timeZone: user.timezone, weekday: 'long', day: 'numeric', month: 'long',
});
const subject = `Votre newsletter Persona du ${date}`;

const blocs = top.map((a) =>
  `<h3 style="margin:16px 0 4px"><a href="${esc(a.url)}">${esc(a.titre)}</a></h3>` +
  `<p style="margin:0 0 4px">${esc(a.resume)}</p>` +
  `<p style="margin:0;color:#777;font-size:12px">${esc(a.source)}</p>`
).join('');

const html =
  `<div style="font-family:Arial,sans-serif;max-width:600px">` +
  `<h2>Votre newsletter du ${esc(date)}</h2>${blocs}` +
  `<hr><p style="font-size:12px;color:#777">Pour te désinscrire, tape /stop dans le chat.</p></div>`;

const text =
  `Votre newsletter du ${date}\n\n` +
  top.map((a) => `${a.titre}\n${a.resume}\n${a.url} (${a.source})`).join('\n\n') +
  `\n\nPour te désinscrire, tape /stop dans le chat.`;

return { json: {
  user_id: user.id,
  email: user.email,
  nb: top.length,
  subject, html, text,
  story_urls: top.map((a) => a.url),
} };
